// Generator for the Corsair peripheral V2 module device table.
// Usage: node scripts/openrgb/port-corsair-peripheral-v2-devices.mjs <openrgb-root> <commit>
// Reads CorsairPeripheralV2ControllerDetect.cpp and regenerates
// modules/corsair-peripheral-v2/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'CorsairPeripheralV2Controller');
const detect = fs.readFileSync(path.join(family, 'CorsairPeripheralV2ControllerDetect.cpp'), 'utf8');
const headerText = fs
  .readdirSync(family, { recursive: true })
  .filter((f) => /\.(cpp|h)$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');
const constants = Object.fromEntries(
  [...headerText.matchAll(/#define\s+([A-Z][A-Z0-9_]*)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
if (constants.CORSAIR_VID == null) throw new Error('CORSAIR_VID not found');
const n = (s) => {
  const t = s.trim();
  if (t in constants) return constants[t];
  if (/^0x[0-9A-Fa-f]+$/.test(t)) return Number.parseInt(t, 16);
  if (/^\d+$/.test(t)) return Number.parseInt(t, 10);
  throw new Error(`unresolved constant ${t}`);
};

// policy: the K70 CORE keyboards (1b1c:1bfd/1bff) are excluded by freeRGB policy.
const EXCLUDED = new Set(['CORSAIR_K70_CORE_RGB_PID', 'CORSAIR_K70_CORE_RGB_TKL_PID', 'CORSAIR_K70_CORE_RGB_V2_PID']);

const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR(?:_I|_IP)?\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*CORSAIR_VID\s*,\s*([A-Z][A-Z0-9_]+)\s*(?:,\s*(\d+)\s*(?:,\s*0x([0-9A-Fa-f]+))?)?\s*\)/g,
)) {
  if (m[2] !== 'DetectCorsairV2SoftwareControllers' && m[2] !== 'DetectCorsairV2HardwareControllers') {
    throw new Error(`unexpected handler ${m[2]} in row ${m[1]}`);
  }
  const pid = n(m[3]);
  if (!Number.isFinite(pid)) throw new Error(`unresolved PID ${m[3]} in row ${m[1]}`);
  if (EXCLUDED.has(m[3])) continue;
  const iface = m[4] != null ? Number.parseInt(m[4], 10) : 255;
  const page = m[5] != null ? Number.parseInt(m[5], 16) : 0xffff;
  rows.push({ name: m[1], handler: m[2], vid: constants.CORSAIR_VID, pid, iface, page });
}
if (rows.length !== 36) throw new Error(`expected 36 non-excluded detector rows, got ${rows.length}`);

const out = path.join(process.cwd(), 'modules', 'corsair-peripheral-v2', 'src', 'devices_table.rs');
fs.mkdirSync(path.dirname(out), { recursive: true });
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-corsair-peripheral-v2-devices.mjs from OpenRGB ${commit}; do not edit.`,
  '// freeRGB policy: the K70 CORE rows (1b1c:1bfd/1bff variants) are not inventoried here.',
  'use crate::table::Detector;',
  '',
  '// interface 255 = any interface; usage_page 65535 = any usage page.',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map((d) =>
    `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${d.iface}, usage_page: ${d.page}, },
`,
  ),
  '];',
  '',
];
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} Corsair V2 HID detectors`);